import { createChart, getGraphicElements } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import { EChartsOption } from '../../../../../src/export/option';
import { CalendarOption } from '../../../../../src/coord/calendar/CalendarModel';
import Element from 'zrender/src/Element';
import ZRText from 'zrender/src/graphic/Text';

function makeOption(calendarOption: CalendarOption): EChartsOption {
    return {
        calendar: [calendarOption],
        series: []
    } as EChartsOption;
}

/**
 * Texts are created by `CalendarView` in this order:
 * year text (1), month texts (n), day texts (7).
 */
function getLabelTexts(chart: EChartsType) {
    const texts = getGraphicElements(chart, 'calendar').filter(
        el => el instanceof ZRText
    ) as ZRText[];
    const dayTexts = texts.slice(texts.length - 7);
    const yearTexts = texts.slice(0, 1);
    const monthTexts = texts.slice(1, texts.length - 7);
    return { yearTexts, monthTexts, dayTexts };
}

function silentOf(els: Element[]) {
    return els.map(el => !!el.silent);
}

describe('calendar_labelSilent', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 600, height: 500 });
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should not be silent by default', function () {
        chart.setOption(makeOption({
            range: '2017-02'
        }));
        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
        expect(yearTexts.length).toBe(1);
        expect(monthTexts.length).toBeGreaterThan(0);
        expect(dayTexts.length).toBe(7);
        expect(silentOf(yearTexts).indexOf(true)).toBe(-1);
        expect(silentOf(monthTexts).indexOf(true)).toBe(-1);
        expect(silentOf(dayTexts).indexOf(true)).toBe(-1);
    });

    it('dayLabel.silent should only silence day labels', function () {
        chart.setOption(makeOption({
            range: '2017-02',
            dayLabel: { silent: true }
        }));
        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
        expect(silentOf(dayTexts).indexOf(false)).toBe(-1);
        expect(silentOf(monthTexts).indexOf(true)).toBe(-1);
        expect(silentOf(yearTexts).indexOf(true)).toBe(-1);
    });

    it('monthLabel.silent should only silence month labels', function () {
        chart.setOption(makeOption({
            range: '2017-02',
            monthLabel: { silent: true }
        }));
        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
        expect(silentOf(monthTexts).indexOf(false)).toBe(-1);
        expect(silentOf(dayTexts).indexOf(true)).toBe(-1);
        expect(silentOf(yearTexts).indexOf(true)).toBe(-1);
    });

    it('yearLabel.silent should only silence the year label', function () {
        chart.setOption(makeOption({
            range: '2017-02',
            yearLabel: { silent: true }
        }));
        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
        expect(silentOf(yearTexts).indexOf(false)).toBe(-1);
        expect(silentOf(monthTexts).indexOf(true)).toBe(-1);
        expect(silentOf(dayTexts).indexOf(true)).toBe(-1);
    });

    it('silent: false should keep labels interactive and visible', function () {
        chart.setOption(makeOption({
            range: '2017-02',
            dayLabel: { silent: false },
            monthLabel: { silent: false },
            yearLabel: { silent: false }
        }));
        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
        const all = ([] as Element[]).concat(yearTexts, monthTexts, dayTexts);
        expect(silentOf(all).indexOf(true)).toBe(-1);
        // Visuals are preserved.
        expect((dayTexts[0].style.text as string).length).toBeGreaterThan(0);
        expect((yearTexts[0].style.text as string).length).toBeGreaterThan(0);
    });

    it('all three can be silenced together', function () {
        chart.setOption(makeOption({
            range: '2017-02',
            dayLabel: { silent: true },
            monthLabel: { silent: true },
            yearLabel: { silent: true }
        }));
        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
        const all = ([] as Element[]).concat(yearTexts, monthTexts, dayTexts);
        expect(silentOf(all).indexOf(false)).toBe(-1);
    });
});
